// Client-side i18n (gettext style): the Azerbaijani source text is the key.
//   t("{n} sual", { n: 3 })  ->  "3 questions" (en) / "3 вопроса" (ru)
// Catalogs live in /static/locales/{en,ru}.json and are generated by tools/i18n_build.py.
// The catalog is loaded with top-level await, so module-level t() calls are already translated.
export const LANGS = [
  { code: "az", label: "Azərbaycanca", short: "AZ", locale: "az-Latn-AZ" },
  { code: "en", label: "English", short: "EN", locale: "en-GB" },
  { code: "ru", label: "Русский", short: "RU", locale: "ru-RU" },
];
const CODES = LANGS.map((l) => l.code);
const KEY = "zeka-lang";

function detect() {
  const qs = new URLSearchParams(location.search);
  const fromUrl = (qs.get("lang") || "").slice(0, 2);
  if (CODES.includes(fromUrl)) { try { localStorage.setItem(KEY, fromUrl); } catch { /* private mode */ } return fromUrl; }
  let saved = null;
  try { saved = localStorage.getItem(KEY); } catch { saved = null; }
  if (CODES.includes(saved)) return saved;
  const nav = (navigator.language || "az").slice(0, 2).toLowerCase();
  return nav === "ru" ? "ru" : nav === "en" ? "en" : "az";
}

export const LANG = detect();
export const DEBUG = new URLSearchParams(location.search).get("i18n") === "debug";
let CAT = {};
if (LANG !== "az") {
  try {
    const r = await fetch(`/static/locales/${LANG}.json`, { cache: "no-cache" });
    CAT = r.ok ? await r.json() : {};
  } catch { CAT = {}; }
}
document.documentElement.lang = LANG;
document.documentElement.dataset.lang = LANG;

export const lang = () => LANG;
export const locale = () => (LANGS.find((l) => l.code === LANG) || LANGS[0]).locale;

function plural(forms, n) {
  const x = Math.abs(Math.trunc(Number(n) || 0));
  if (LANG === "ru") {
    const m10 = x % 10, m100 = x % 100;
    const k = m10 === 1 && m100 !== 11 ? "one" : m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14) ? "few" : "many";
    return forms[k] || forms.other || forms.many || "";
  }
  return (x === 1 && forms.one) || forms.other || forms.many || forms.one || "";
}

export function t(src, params) {
  if (src == null) return "";
  let s = String(src);
  if (LANG !== "az") {
    const v = CAT[s];
    if (v == null || v === "") { if (DEBUG) s = `⟦${s}⟧`; }
    else s = typeof v === "object" ? plural(v, params && params.n) : v;
  }
  if (params) s = s.replace(/\{(\w+)\}/g, (m, k) => (k in params ? String(params[k] ?? "") : m));
  return s;
}

// Pick the current language from an {az, en, ru} object (content that ships translated).
export const tl = (o) => (o && typeof o === "object" ? o[LANG] || o.az || "" : o ?? "");

export function setLang(code) {
  if (!CODES.includes(code) || code === LANG) return false;
  try { localStorage.setItem(KEY, code); } catch { /* ignore */ }
  return true;
}

